package jp.personal.hanshinedge.validation;
import android.app.Instrumentation;import android.content.Intent;import android.view.*;import android.widget.TextView;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import jp.personal.hanshinedge.ui.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)public class MainActivityTest {
 private Instrumentation instrumentation;private MainActivity activity;
 @Before public void launch(){instrumentation=InstrumentationRegistry.getInstrumentation();Intent intent=new Intent(instrumentation.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)instrumentation.startActivitySync(intent);instrumentation.waitForIdleSync();}
 @After public void close(){if(activity!=null)instrumentation.runOnMainSync(()->activity.finish());}
 private String text(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText()).append('\n');if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(text(((ViewGroup)v).getChildAt(i)));return s.toString();}
 private String screen(){final String[] s={null};instrumentation.runOnMainSync(()->s[0]=text(activity.getWindow().getDecorView()));return s[0];}
 private JSONObject fixture(boolean jump)throws Exception{String raw=new java.util.Scanner(instrumentation.getContext().getAssets().open("jra-real-historical-fixture-20260919-20261114.json"),"UTF-8").useDelimiter("\\A").next();JSONArray rows=new JSONObject(raw).getJSONArray("races");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(r.getString("venue_code").equals("09")&&r.getBoolean("obstacle")==jump)return r;}throw new IllegalStateException("FIXTURE_MISSING");}
 @Test public void launcherAndTodayHeading(){assertTrue(screen().contains("JRA-EDGE"));assertTrue(screen().contains("本日の開催"));assertTrue(screen().contains("REAL MONEY: BLOCKED"));}
 @Test public void historicalDetailBlocksFormalBuy()throws Exception{JSONObject r=fixture(false);instrumentation.runOnMainSync(()->activity.showRace(r));assertTrue(screen().contains(r.getString("race_name")));assertTrue(screen().contains("NOT_PROSPECTIVE"));assertTrue(screen().contains("出走馬"));}
 @Test public void obstacleBlocksFlatModel()throws Exception{JSONObject r=fixture(true);instrumentation.runOnMainSync(()->activity.showRace(r));assertTrue(screen().contains("OBSTACLE_MODEL_BLOCKED"));assertTrue(screen().contains("UNKNOWN"));}
 @Test public void missingF0AndPaperScreen()throws Exception{JSONObject r=fixture(false);r.put("REAL_PROSPECTIVE",true);instrumentation.runOnMainSync(()->activity.showRace(r));assertTrue(screen().contains("F0_NOT_READY"));assertTrue(screen().contains("UNKNOWN"));instrumentation.runOnMainSync(()->activity.paper());assertTrue(screen().contains("¥100,000"));}
 @Test public void suppliedF0DisplaysProviderOutput()throws Exception{JSONObject r=fixture(false);r.put("REAL_PROSPECTIVE",true).put("odds_retrieved_at",System.currentTimeMillis());JSONArray rows=r.getJSONArray("runners");for(int i=0;i<rows.length();i++)rows.getJSONObject(i).put("win_odds",2.0+i).put("f0",1.0+i);instrumentation.runOnMainSync(()->activity.showRace(r));assertTrue(screen().contains("総合勝率"));assertTrue(screen().contains("市場勝率"));assertFalse(screen().contains("総合勝率: UNKNOWN"));assertTrue(screen().contains("REAL MONEY: BLOCKED"));}
}
